package com.zest.products.auth;
import jakarta.persistence.*; import java.util.*;
@Entity @Table(name="app_user",indexes=@Index(name="idx_user_username",columnList="username",unique=true)) public class AppUser { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true,length=100) private String username; @Column(nullable=false) private String password; @ElementCollection(fetch=FetchType.EAGER) @CollectionTable(name="user_roles",joinColumns=@JoinColumn(name="user_id")) @Column(name="role") private Set<String> roles=new HashSet<>(); public Long getId(){return id;} public String getUsername(){return username;} public void setUsername(String v){username=v;} public String getPassword(){return password;} public void setPassword(String v){password=v;} public Set<String> getRoles(){return roles;} }
